                            <slot name=\"after-checkout-button\"></slot>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n        <div class=\"basket-preview-overlay\" v-toggle-basket-preview></div>\n    </div>\n</template>\n\n<script>\nimport ApiService from \"../../services/ApiService\";\nimport { mapState } from \"vuex\";\n\nexport default {\n    name: \"basket-preview\",\n\n    props:\n    {\n        showNetPrices:\n        {\n            type: Boolean,\n            default: false\n        },\n        visibleFields:\n        {\n            type: Array,\n            default: () => [\n                \"basketValueNet\",\n                \"basketValueGross\",\n                \"rebate\",\n                \"shippingCostsNet\",\n                \"shippingCostsGross\",\n                \"promotionCoupon\",\n                \"totalSumNet\",\n                \"vats\",\n                \"additionalCosts\",\n                \"totalSumGross\",\n                \"salesCoupon\",\n                \"openAmount\",\n                \"subAmount\"\n            ]\n        }\n    },\n\n    computed: {\n        hover()\n        {\n            return App.config.basket.previewType === 'hover';\n        },\n\n        showShippingCountrySelect()\n        {\n            return App.config.basket.showShippingCountrySelect;\n        },\n\n        ...mapState({\n            basket: state => state.basket.data,\n            basketItems: state => state.basket.items,\n            basketNotifications: state => state.basket.basketNotifications,\n            isBasketItemQuantityUpdate: state => state.basket.isBasketItemQuantityUpdate\n        })\n    },\n\n    /**\n     * Bind to basket and bind the basket items\n     */\n    mounted()\n    {\n        if (App.config.basket.addItemToBasketConfirm === \"preview\")\n        {\n            ApiService.listen(\"AfterBasketItemAdd\", data =>\n            {\n                this.show();