AACA;AACA,6BAA6B,2BAA2B;AACxD;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,8BAA8B,SAAS,+BAA+B,EAAE;AACxE;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,aAAa;AACb;AACA;AACA;AACA;AACA;AACA,eAAe,0BAA0B;AACzC;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,6BAA6B;AAC7B;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,6BAA6B;AAC7B;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,uBAAuB;AACvB;AACA;AACA;AACA;AACA;AACA;AACA;AACA,yBAAyB,SAAS,yCAAyC,EAAE;AAC7E;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,kCAAkC,yCAAyC;AAC3E,kCAAkC;AAClC,yBAAyB;AACzB;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,gCAAgC,kCAAkC;AAClE;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,kCAAkC;AAClC,yBAAyB;AACzB;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,gCAAgC,kCAAkC;AAClE;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,kCAAkC;AAClC,yBAAyB;AACzB;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,mBAAmB,wCAAwC;AAC3D;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;;;;;;;;;;;;;;AC/jBA;AAAA;AAAA;AAAA;AAA2F;AAC3B;AACL;;;AAG3D;AACsG;AACtG,gBAAgB,2GAAU;AAC1B,EAAE,kFAAM;AACR,EAAE,uFAAM;AACR,EAAE,gGAAe;AACjB;AACA;AACA;AACA;;AAEA;;AAEA;AACA,IAAI,KAAU,EAAE,YAiBf;AACD;AACe,gF;;;;;;;;;;;;ACtCf;AAAA;AAAA,wCAAoM,CAAgB,gPAAG,EAAC,C;;;;;;;;;;;;ACAxN;AAAA;AAAA;AAAA;AAAA;AAAA","file":"chunks/ceres-21.js","sourcesContent":["<template>\n    <div class=\"cmp-totals\">\n        <div class=\"h3\">{{ $translate(\"Ceres::Template.basketSum\") }}</div>\n        <div class=\"component-loading with-icon refreshing\" :class=\"{ 'is-loading': isBasketLoading }\">\n            <dl>\n                <slot name=\"before-item-sum\"></slot>\n\n                <!-- Basket value (net) -->\n                <template v-if=\"visibleFields.includes('basketValueNet') && basket.basketAmountNet != basket.basketAmount\">\n                    <dt :class=\"{ 'font-weight-bold': showNetPrices }\">\n                        {{ $translate(\"Ceres::Template.basketValue\") }} {{ $translate(\"Ceres::Template.basketNet\") }}\n                    </dt><!--\n                    --><dd :class=\"{ 'font-weight-bold': showNetPrices }\" data-testing=\"item-sum-net\">\n                        {{ calculateBaseValue(basket.itemSumNet, basket.basketRebate) | currency }}\n                    </dd>\n                </template>\n                <!-- Basket value (net) -->\n\n                <!-- Basket value (gross) -->\n                <template v-if=\"visibleFields.includes('basketValueGross')\">\n                    <dt :class=\"{ 'font-weight-bold': !showNetPrices }\">\n                        {{ $translate(\"Ceres::Template.basketValue\") }} <span v-if=\"basket.basketAmountNet != basket.basketAmount\">{{ $translate(\"Ceres::Template.basketGross\") }}</span>\n                    </dt><!--\n                    --><dd :class=\"{ 'font-weight-bold': !showNetPrices }\" data-testing=\"item-sum\">\n                        {{ calculateBaseValue(basket.itemSum, basket.basketRebate)| currency  }}\n                    </dd>\n                </template>\n                <!-- Basket value (gross) -->\n\n                <!-- Rebate -->\n                <template v-if=\"visibleFields.includes('rebate') && basket.basketRebate\">\n                    <dt class=\"rebate-hint\">\n                        {{ $translate(\"Ceres::Template.basketRebate\") }}\n                    </dt><!--\n                --><dd class=\"rebate-hint\" v-if=\"!showNetPrices\">\n                        {{ $translate(\"Ceres::Template.basketRebateSign\") }}${calculateBaseValue(basket.itemSum, basket.basketRebate) - basket.itemSum | currency }\n                    </dd><!--\n                --><dd class=\"rebate-hint\" v-else>\n                        {{ $translate(\"Ceres::Template.basketRebateSign\") }}{{ calculateBaseValue(basket.itemSumNet, basket.basketRebate) - basket.itemSumNet | currency  }}\n                    </dd>\n                    <dt :class=\"{ 'font-weight-bold': showNetPrices }\">\n                        {{ $translate(\"Ceres::Template.basketSubTotal\") }} {{ $translate(\"Ceres::Template.basketNet\") }}\n                    </dt><!--\n                --><dd :class=\"{ 'font-weight-bold': showNetPrices }\">\n                        {{ basket.itemSumNet | currency }}\n                    </dd>\n                    <dt :class=\"{ 'font-weight-bold': !showNetPrices }\">\n                        {{ $translate(\"Ceres::Template.basketSubTotal\") }} <span v-if=\"basket.basketAmountNet != basket.basketAmount\">{{ $translate(\"Ceres::Template.basketGross\") }}</span>\n                    </dt><!--\n                --><dd :class=\"{ 'font-weight-bold': !showNetPrices }\">\n                        {{ basket.itemSum | currency }}\n                    </dd>\n                </template>\n                <!-- Rebate -->\n\n\n                <slot name=\"after-item-sum\"></slot>\n\n                <slot name=\"before-shipping-costs\"></slot>\n\n                <!-- Shipping (net) -->\n                <template v-if=\"visibleFields.includes('shippingCostsNet') && basket.basketAmountNet != basket.basketAmount\">\n                    <dt :class=\"{ 'font-weight-bold': showNetPrices }\">\n                        {{ $translate(\"Ceres::Template.basketShippingCosts\") }} {{ $translate(\"Ceres::Template.basketNet\") }}\n                    </dt><!--\n                    --><dd :class=\"{ 'font-weight-bold': showNetPrices }\" data-testing=\"shipping-amount-net\">\n                        {{ basket.shippingAmountNet | currency }}\n                    </dd>\n                </template>\n                <!-- Shipping (net) -->\n\n                <!-- Shipping (gross) -->\n                <template v-if=\"visibleFields.includes('shippingCostsGross')\">\n                    <dt :class=\"{ 'font-weight-bold': !showNetPrices }\">\n                        {{ $translate(\"Ceres::Template.basketShippingCosts\") }} <span v-if=\"basket.basketAmountNet != basket.basketAmount\">{{ $translate(\"Ceres::Template.basketGross\") }}</span>\n                    </dt><!--\n                    --><dd :class=\"{ 'font-weight-bold': !showNetPrices }\" data-testing=\"shipping-amount\">\n                        {{ basket.shippingAmount | currency }}\n                    </dd>\n                </template>\n                <!-- Shipping (gross) -->\n\n                <slot name=\"after-shipping-costs\"></slot>\n\n                <!-- Coupon -->\n                <template v-if=\"visibleFields.includes('promotionCoupon') && basket.couponCode && basket.couponCampaignType === 'promotion'\">\n                    <dt class=\"font-weight-bold\">\n                        {{ $translate(\"Ceres::Template.basketCoupon\") }}\n                    </dt><!--\n                --><dd class=\"font-weight-bold\" data-testing=\"promotion-coupon\">\n                        {{ basket.couponDiscount | currency }}\n                    </dd>\n                </template>\n                <!-- Coupon -->\n\n                <hr v-if=\"basket.basketAmountNet != basket.basketAmount\">\n                <slot name=\"before-total-sum\"></slot>\n\n                <!-- Total sum (net) -->\n                <template v-if=\"visibleFields.includes('totalSumNet') && basket.basketAmountNet != basket.basketAmount\">\n                    <dt :class=\"{ 'font-weight-bold': showNetPrices }\">\n                        {{ $translate(\"Ceres::Template.basketTotalSum\") }} {{ $translate(\"Ceres::Template.basketNet\") }}\n                    </dt><!--\n                    --><dd :class=\"{ 'font-weight-bold': showNetPrices }\" data-testing=\"basket-amount-net\">\n                        {{ basket.basketAmountNet | currency }}\n                    </dd>\n                </template>\n                <!-- Total sum (net) -->\n\n                <slot name=\"before-vat\"></slot>\n\n                <!-- VAT -->\n                <div v-if=\"visibleFields.includes('vats')\" class=\"vatTotals\" v-for=\"totalVat in basket.totalVats\">\n                    <dt>\n                        {{ $translate(\"Ceres::Template.basketVAT\") }} {{ totalVat.vatValue }}%\n                    </dt><!--\n                    --><dd data-testing=\"vat-amount\">\n                        {{ totalVat.vatAmount | currency }}\n                    </dd>\n                </div>\n                <!-- VAT -->\n\n                <slot name=\"after-vat\"></slot>\n\n                <div class=\"totalSum\">\n                    <hr>\n                    <!-- AdditionalCosts -->\n                    <template v-if=\"visibleFields.includes('additionalCosts') && propertiesWithAdditionalCosts.length\">\n                        <template v-for=\"property in propertiesWithAdditionalCosts\">\n                            <dt class=\"font-weight-bold\" :key=\"'property-name-' + property.propertyId\">\n                                {{ property.name }}\n                            </dt><!--\n                            --><dd class=\"font-weight-bold\" :key=\"'property-price-' + property.propertyId\">\n                                {{ property.price | currency }}\n                            </dd>\n                        </template>\n                    </template>\n                    <!-- AdditionalCosts -->\n\n                    <!-- Total sum (gross) -->\n                    <template v-if=\"visibleFields.includes('totalSumGross')\">\n                        <dt :class=\"{ 'font-weight-bold': !showNetPrices }\">\n                            {{ $translate(\"Ceres::Template.basketTotalSum\") }} <span v-if=\"basket.basketAmountNet != basket.basketAmount\">{{ $translate(\"Ceres::Template.basketGross\") }}</span>\n                        </dt><!--\n                        --><dd :class=\"{ 'font-weight-bold': !showNetPrices }\" data-testing=\"basket-amount\">\n                            {{ basket.basketAmount | currency }}\n                        </dd>\n                    </template>\n                    <!-- Total sum (gross) -->\n\n                    <!-- Coupon -->\n                    <template v-if=\"visibleFields.includes('salesCoupon') && basket.couponCode && basket.couponCampaignType === 'sales'\">\n                        <dt class=\"font-weight-bold\">\n                            {{ $translate(\"Ceres::Template.basketCoupon\") }}\n                        </dt><!--\n                     --><dd class=\"font-weight-bold\" data-testing=\"sales-coupon\">\n                            {{ basket.couponDiscount | currency }}\n                        </dd>\n                    </template>\n                    <!-- Coupon -->\n\n                    <!-- Coupon open amount -->\n                    <template v-if=\"visibleFields.includes('openAmount') && basket.couponCampaignType === 'sales'\">\n                        <dt class=\"font-weight-bold\">\n                            {{ $translate(\"Ceres::Template.basketOpenAmount\") }}\n                        </dt><!--\n                    --><dd class=\"font-weight-bold\" data-testing=\"open-amount\">\n                            {{ basket.openAmount | currency }}\n                        </dd>\n                    </template>\n                    <!-- Coupon open amount -->\n                </div>\n\n                <slot name=\"after-total-sum\"></slot>\n            </dl>\n        </div>\n\n        <div v-if=\"basket.isExportDelivery && deliveryExportTranslation\" class=\"alert alert-info w-100\">\n            {{ deliveryExportTranslation }}\n        </div>\n    </div>\n</template>\n\n<script>\nimport { mapState } from \"vuex\";\n\nexport default {\n\n    props:\n    {\n        visibleFields:\n        {\n            type: Array,\n            default: () => [\n                \"basketValueNet\",\n                \"basketValueGross\",\n                \"rebate\",\n                \"shippingCostsNet\",\n                \"shippingCostsGross\",\n                \"promotionCoupon\",\n                \"totalSumNet\",\n                \"vats\",\n                \"additionalCosts\",\n                \"totalSumGross\",\n                \"salesCoupon\",\n                \"openAmount\"\n            ]\n        }\n    },\n\n    computed:\n    {\n        currentShippingCountry()\n        {\n            const shippingCountryId = this.basket.shippingCountryId;\n\n            return this.shippingCountries.find(country => country.id === shippingCountryId);\n        },\n\n        shopCountry()\n        {\n            const shopCountryId = this.basket.shopCountryId;\n\n            return this.shippingCountries.find(country => country.id === shopCountryId);\n        },\n\n        deliveryExportTranslation()\n        {\n            const shopCountry = this.shopCountry && this.shopCountry.currLangName;\n            const currentShippingCountry = this.currentShippingCountry && this.currentShippingCountry.currLangName;\n\n            return this.$translate(\"Ceres::Template.basketExportDeliveryWarning\", { from: shopCountry, to: currentShippingCountry });\n        },\n\n        propertiesWithAdditionalCosts()\n        {\n            const entries = [];\n\n            for (const basketItem of this.basketItems) {\n                const matchingProperties = basketItem.variation.data.properties.filter(property =>\n                    property.property.isShownAsAdditionalCosts && property.property.isOderProperty === false\n                );\n\n                for (const property of matchingProperties) {\n                    const existingEntry = entries.find(entry => entry.propertyId === property.propertyId)\n\n                    if (!existingEntry) {\n                        entries.push({\n                            propertyId: property.propertyId,\n                            name: property.property.names.name,\n                            quantity: basketItem.quantity,\n                            surcharge: this.$options.filters.propertySurcharge(basketItem.variation.data.properties, property.propertyId)\n                        });\n                    }\n                    else {\n                        existingEntry.quantity += basketItem.quantity\n                    }\n                }\n            }\n\n            for (const entry of entries) {\n                entry.price = entry.quantity * entry.surcharge;\n            }\n\n            return entries;\n        },\n\n        ...mapState({\n            basket: state => state.basket.data,\n            basketItems: state => state.basket.items,\n            isBasketLoading: state => state.basket.isBasketLoading,\n            shippingCountries: state => state.localization.shippingCountries,\n            showNetPrices: state => state.basket.showNetPrices\n        })\n    },\n\n    methods: {\n        calculateBaseValue(value, percent)\n        {\n            return (value / (100 - percent)) * 100;\n        }\n    }\n}\n</script>\n","var render = function() {\n  var _vm = this\n  var _h = _vm.$createElement\n  var _c = _vm._self._c || _h\n  return _c(\"div\", { staticClass: \"cmp-totals\" }, [\n    _c(\"div\", { staticClass: \"h3\" }, [\n      _vm._v(_vm._s(_vm.$translate(\"Ceres::Template.basketSum\")))\n    ]),\n    _vm._v(\" \"),\n    _c(\n      \"div\",\n      {\n        staticClass: \"component-loading with-icon refreshing\",\n        class: { \"is-loading\": _vm.isBasketLoading }\n      },\n      [\n        _c(\n          \"dl\",\n          [\n            _vm._t(\"before-item-sum\"),\n            _vm._v(\" \"),\n            _vm.visibleFields.includes(\"basketValueNet\") &&\n            _vm.basket.basketAmountNet != _vm.basket.basketAmount\n              ? [\n                  _c(\n                    \"dt\",\n                    { class: { \"font-weight-bold\": _vm.showNetPrices } },\n                    [\n 